values ('fq_star_098', 'Home Earned: The Unquiet Machine 05', 'boss', 'S', 'STARFORGED_LEGION', 'ETERNAL_GATE', 'Home Earned: Hold the Eternal Gate and forge an honorable settlement amid the planetary crisis. Legion command designates this target a test of discipline and battlefield resolve. In Eternal Gate, defeat Abyss Harbinger (x1) to secure the next piece of the operation.', '{"npc_id": "npc_legion_class_trainer", "name": "Centurion Valka", "location": "ETERNAL_GATE"}'::jsonb, '{"min_level": 97, "reputation_required": 44728, "required_quests": ["fq_star_097"], "required_items": [], "party_required": true, "raid_size": 4}'::jsonb, '[{"objective_id": "primary_target", "type": "kill", "target": 4002, "target_code": "ABYSS_HARBINGER", "count": 1, "description": "Defeat Abyss Harbinger (x1)."}]'::jsonb, '{"exp": 15480, "currency": 5880, "crd": 788, "rep": 2210, "reputation": 2210, "items": [{"item_id": "itm_phoenix_core", "quantity": 1}]}'::jsonb, false, false, 'fq_star_099', false, NULL, NULL, NULL, 'quest_legion.json', 97)
